    }

    /**
     * The status this claim had at the end of the day, as its status log records it (the last line on or before it);
     * null when it was not yet added then. A claim kept from before the log (no lines) has its status now.
     */
    public ClaimStatus statusOn(LocalDate end) {
        if (log == null || log.isEmpty()) {
            return status;
        }
        ClaimStatus then = null;
        for (ClaimLogLine line : log) {
            if (!LocalDate.parse(line.on()).isAfter(end)) {
                then = line.status();
            }
        }
        return then;
    }

    /** Whether this claim's statement binds its figure: it is stated, and not PENDING (which shows its live figure). */
    public boolean bound() {
        return stated && status != ClaimStatus.PENDING;
    }

    /**
     * Whether this claim keeps a figure whatever the rates: fixed when settled, or bound by a statement (a claim
     * settled or bound when its grade had no rate keeps none; a PENDING claim is not bound).
     */
    public boolean fixed() {
        return settledDue != null || (bound() && statedDue != null);
    }

    /**
     * This claim's due: the due fixed when settled; else the greater of the sheet's floor in force on its date and its
     * {@link #figure} plus, while it is overdue, its late charge on that figure (a correction has no floor and no
     * charge); null when there is no figure.
     */
    public BigDecimal due(List<Rate> rates, String grade, Dated floor, Late late) {
        BigDecimal figure = figure(rates, grade, floor, late.rounding(this));
        if (figure == null || settledDue != null || correction()) {
            return figure;
        }
        return figure.add(late.charge(this, figure)).max(floor.on(date));
    }

    /**
     * This claim's figure: the due fixed when settled, else the rate figure its statement bound (unless PENDING), else
     * its amount at the grade's rate in force on its date (the floor is applied last, in {@link #due}); null when
     * there is none.
     */
    public BigDecimal figure(List<Rate> rates, String grade, Dated floor) {
        return figure(rates, grade, floor, RoundingMode.HALF_EVEN);
    }

    /** This claim's {@link #figure}, its live figure rounded by the mode. */
    public BigDecimal figure(List<Rate> rates, String grade, Dated floor, RoundingMode rounding) {
        if (settledDue != null) {
            return new BigDecimal(settledDue);
        }
        if (bound()) {
            return statedDue == null ? null : new BigDecimal(statedDue);
        }
        return Rate.due(amount, Rate.on(rates, grade, LocalDate.parse(date)), rounding);
    }
}

package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.sql.Date;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

/** The claims kept per sheet, each belonging to a person on that sheet. */
@Repository
public class Claims {

    private static final RowMapper<Claim> ROW = (rs, i) -> new Claim(rs.getLong("id"), rs.getLong("person"),
            rs.getBigDecimal("amount").setScale(2, RoundingMode.UNNECESSARY).toPlainString(),
            rs.getDate("claimed_on").toLocalDate().toString(), rs.getString("note"),
            ClaimStatus.valueOf(rs.getString("status")), rs.getObject("number_on_sheet", Integer.class),
            rs.getBigDecimal("settled_due") == null ? null
                    : rs.getBigDecimal("settled_due").setScale(2, RoundingMode.UNNECESSARY).toPlainString(),
            rs.getString("opened_by"), rs.getBoolean("stated"),
            rs.getBigDecimal("stated_due") == null ? null
                    : rs.getBigDecimal("stated_due").setScale(2, RoundingMode.UNNECESSARY).toPlainString(),
            rs.getString("corrects"), rs.getDate("rounds_on").toLocalDate().toString(),
            rs.getString("period_number"), rs.getDate("due_by").toLocalDate().toString(), List.of(),
            rs.getDate("deferred_until") == null ? null : rs.getDate("deferred_until").toLocalDate().toString(),
            rs.getBoolean("deferred"), rs.getInt("proofs"), rs.getString("split_from"),
            rs.getString("locked_by"), rs.getBoolean("late_entry"));

    // A claim rounds on its own date; a correction on the date of the claim it corrects (its own when none has it).
    // It is deferred while OPEN with its deferred-until after the sheet's today (the real date until one is set).
    private static final String COLUMNS = "SELECT claim.id, claim.person, claim.amount, claim.claimed_on, claim.note, claim.status,"
            + " claim.number_on_sheet, claim.settled_due, claim.opened_by, claim.stated, claim.stated_due, claim.corrects,"
            + " claim.period_number, claim.due_by, COALESCE(corrected.claimed_on, claim.claimed_on) AS rounds_on,"
            + " claim.deferred_until, claim.proofs, claim.split_from, claim.locked_by, claim.late_entry, (claim.status = 'OPEN' AND claim.deferred_until IS NOT NULL AND claim.deferred_until >"
            + " COALESCE((SELECT s.today FROM sheet s WHERE s.id = claim.sheet), CURRENT_DATE)) AS deferred FROM claim"
            + " LEFT JOIN claim corrected ON corrected.sheet = claim.sheet AND "
            + " COALESCE(corrected.period_number, CAST(corrected.number_on_sheet AS VARCHAR)) = claim.corrects";

    // The place after every claim listed on the sheet (bound to the sheet), so the claim lists newest.
    private static final String NEXT_LISTED = "(SELECT COALESCE(MAX(l.listed), 0) + 1 FROM claim l WHERE l.sheet = ?)";

    private final JdbcTemplate jdbc;

    public Claims(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    private static final String LOG = "SELECT claim, status, by_user, on_date, due FROM claim_log WHERE sheet = ?";

    /** Every claim on the sheet, newest first. */
    public List<Claim> list(String sheet) {
        return withLogs(sheet, jdbc.query(COLUMNS + " WHERE claim.sheet = ? ORDER BY claim.listed DESC, claim.id DESC", ROW, sheet),
                jdbc.query(LOG + " ORDER BY id", LOG_ROW, sheet));
    }

    public Claim find(String sheet, long id) {
        List<Claim> found = jdbc.query(COLUMNS + " WHERE claim.sheet = ? AND claim.id = ?", ROW, sheet, id);
        return found.isEmpty() ? null
                : withLogs(sheet, found, jdbc.query(LOG + " AND claim = ? ORDER BY id", LOG_ROW, sheet, id)).get(0);
    }

    private record Logged(long claim, ClaimLogLine line) {
    }

    private static final RowMapper<Logged> LOG_ROW = (rs, i) -> new Logged(rs.getLong("claim"),
            new ClaimLogLine(ClaimStatus.valueOf(rs.getString("status")), rs.getString("by_user"),
                    rs.getDate("on_date").toLocalDate().toString(), rs.getString("due")));

    /** The claims, each with its own lines of the status log (oldest first). */
    private static List<Claim> withLogs(String sheet, List<Claim> found, List<Logged> logged) {
        Map<Long, List<ClaimLogLine>> lines = new HashMap<>();
        for (Logged l : logged) {
            lines.computeIfAbsent(l.claim(), k -> new ArrayList<>()).add(l.line());
        }
        return found.stream().map(c -> c.withLog(lines.getOrDefault(c.id(), List.of()))).toList();
    }

    /** The claim showing this number on the sheet (within its period, or on the sheet), or null when none does. */
    public Claim findByNumber(String sheet, String number) {
        List<Claim> found = jdbc.query(COLUMNS + " WHERE claim.sheet = ?"
                + " AND COALESCE(claim.period_number, CAST(claim.number_on_sheet AS VARCHAR)) = ?", ROW, sheet, number);
        return found.isEmpty() ? null : found.get(0);
    }

    /** Adds the claim with its due-by, fixed now and never moved after; returns its id. */
    public long add(String sheet, long person, ClaimInput input, LocalDate dueBy) {
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            var ps = con.prepareStatement("INSERT INTO claim (sheet, person, amount, claimed_on, note, corrects, due_by, listed)"
                    + " VALUES (?, ?, ?, ?, ?, ?, ?, " + NEXT_LISTED + ")", new String[] { "id" });
            ps.setString(1, sheet);
            ps.setLong(2, person);
            ps.setBigDecimal(3, input.amount());
            ps.setDate(4, Date.valueOf(input.date()));
            ps.setString(5, input.note());
            ps.setString(6, input.corrects());
            ps.setDate(7, Date.valueOf(dueBy));
            ps.setString(8, sheet);
            return ps;
        }, keys);
        return keys.getKey().longValue();
    }

    /** Marks the claim a late entry: added while the period its date falls in was soft-closed. */
    public void setLateEntry(String sheet, long id) {
        jdbc.update("UPDATE claim SET late_entry = TRUE WHERE sheet = ? AND id = ?", sheet, id);
    }

    /**
     * Adds the OPEN claim split off another: the amount, with the date and note of the claim it was split from (by
     * the number that claim shows), opened by the user, with its due-by fixed now; returns its id.
     */
    public long addSplit(String sheet, long person, BigDecimal amount, LocalDate date, String note, LocalDate dueBy,
            String splitFrom, String openedBy) {
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            var ps = con.prepareStatement("INSERT INTO claim (sheet, person, amount, claimed_on, note, due_by, status,"
                    + " split_from, opened_by, listed) VALUES (?, ?, ?, ?, ?, ?, 'OPEN', ?, ?, " + NEXT_LISTED + ")",
                    new String[] { "id" });
            ps.setString(1, sheet);
            ps.setLong(2, person);
            ps.setBigDecimal(3, amount);
            ps.setDate(4, Date.valueOf(date));
            ps.setString(5, note);
            ps.setDate(6, Date.valueOf(dueBy));
            ps.setString(7, splitFrom);
            ps.setString(8, openedBy);
            ps.setString(9, sheet);
            return ps;
        }, keys);
        return keys.getKey().longValue();
    }

    /**
     * Leaves an OPEN claim the rest of its amount once split, unbound from any statement; conditional on the
     * amount read and on it still being OPEN and not deferred: false when it no longer is.
     */
    public boolean split(String sheet, long id, BigDecimal was, BigDecimal rest) {
        return jdbc.update("UPDATE claim SET amount = ?, stated = FALSE, stated_due = NULL WHERE sheet = ? AND id = ?"
                + " AND status = 'OPEN' AND amount = ? AND (deferred_until IS NULL OR deferred_until <="
                + " COALESCE((SELECT s.today FROM sheet s WHERE s.id = claim.sheet), CURRENT_DATE))",
                rest, sheet, id, was) == 1;
    }

    /**
     * Edits a draft claim not locked by another user's editor, releasing any lock on it: false when it is no longer a
     * draft, or another user's editor holds it.
     */
    public boolean update(String sheet, long id, ClaimInput input, String user) {
        return jdbc.update(
                "UPDATE claim SET amount = ?, claimed_on = ?, note = ?, corrects = ?, locked_by = NULL WHERE sheet = ? AND id = ?"
                        + " AND status = 'DRAFT' AND (locked_by IS NULL OR locked_by = ?)",
                input.amount(), Date.valueOf(input.date()), input.note(), input.corrects(), sheet, id, user) == 1;
    }

    /**
     * Locks a draft claim for the user's editor, releasing any other claim the user's editor held on the sheet:
     * false when it is no longer a draft, or another user's editor holds it.
     */
    public boolean lock(String sheet, long id, String user) {
        if (jdbc.update("UPDATE claim SET locked_by = ? WHERE sheet = ? AND id = ? AND status = 'DRAFT'"
                + " AND (locked_by IS NULL OR locked_by = ?)", user, sheet, id, user) != 1) {
            return false;
        }
        jdbc.update("UPDATE claim SET locked_by = NULL WHERE sheet = ? AND id <> ? AND locked_by = ?", sheet, id, user);
        return true;
    }

    /** Releases the claim's lock when the user's editor holds it. */
    public void unlock(String sheet, long id, String user) {
        jdbc.update("UPDATE claim SET locked_by = NULL WHERE sheet = ? AND id = ? AND locked_by = ?", sheet, id, user);
    }

    /** Releases every lock on the sheet's claims, as when its today changes. */
    public void unlockAll(String sheet) {
        jdbc.update("UPDATE claim SET locked_by = NULL WHERE sheet = ? AND locked_by IS NOT NULL", sheet);
    }

    /**
     * Moves the claim of the person and status it was read with to another person, unbound from any statement and
     * listed as the sheet's newest: false when it no longer has that person or status.
     */
    public boolean reassign(String sheet, long id, long from, ClaimStatus status, long to) {
        return jdbc.update("UPDATE claim SET person = ?, stated = FALSE, stated_due = NULL, listed = " + NEXT_LISTED
                + " WHERE sheet = ? AND id = ? AND person = ? AND status = ?", to, sheet, sheet, id, from,
                status.name()) == 1;
    }

    /**
     * Moves the claim of the status and date it was read with to another date, keeping its due-by and any figure its
     * statement bound: false when it no longer has that status or date.
     */
    public boolean redate(String sheet, long id, ClaimStatus status, LocalDate was, LocalDate date) {
        return jdbc.update("UPDATE claim SET claimed_on = ? WHERE sheet = ? AND id = ? AND status = ? AND claimed_on = ?",
                Date.valueOf(date), sheet, id, status.name(), Date.valueOf(was)) == 1;
    }

    /** Moves the claim from one status to another: false when it no longer has the status it was read with. */
    public boolean changeStatus(String sheet, long id, ClaimStatus from, ClaimStatus to) {
        return jdbc.update("UPDATE claim SET status = ? WHERE sheet = ? AND id = ? AND status = ?", to.name(), sheet,
                id, from.name()) == 1;
    }

    /** Defers an OPEN claim until the date: false when it is no longer OPEN. */
    public boolean defer(String sheet, long id, LocalDate until) {
        return jdbc.update("UPDATE claim SET deferred_until = ? WHERE sheet = ? AND id = ? AND status = 'OPEN'",
                Date.valueOf(until), sheet, id) == 1;
    }

    /**
     * Raises the claim's proofs count by one, conditional on the status and count read, so a concurrent change by
     * another user is refused, not overwritten: false when it was not.
     */
    public boolean addProof(String sheet, long id, ClaimStatus status, int was) {
        return jdbc.update("UPDATE claim SET proofs = proofs + 1 WHERE sheet = ? AND id = ? AND status = ? AND proofs = ?",
                sheet, id, status.name(), was) == 1;
    }

    /** Fixes the claim's due as it is settled, or leaves none with null. */
    public void setSettledDue(String sheet, long id, BigDecimal due) {
        jdbc.update("UPDATE claim SET settled_due = ? WHERE sheet = ? AND id = ?", due, sheet, id);
    }

    /**
     * Re-fixes a SETTLED claim's due (null for none), conditional on the due read, so a concurrent change by another
     * user is refused, not overwritten; false when it was not.
     */
    public boolean resettle(String sheet, long id, BigDecimal was, BigDecimal due) {
        return jdbc.update("UPDATE claim SET settled_due = ? WHERE sheet = ? AND id = ? AND status = ?"
                + " AND settled_due IS NOT DISTINCT FROM ?", due, sheet, id, ClaimStatus.SETTLED.name(), was) == 1;
    }

    /** Binds the claim to a statement's figure (null when its grade had no rate), or unbinds it when not stated. */
    public void setStated(String sheet, long id, boolean stated, BigDecimal due) {
        jdbc.update("UPDATE claim SET stated = ?, stated_due = ? WHERE sheet = ? AND id = ?", stated, due, sheet, id);
    }

    /** Unbinds every claim of the person bound by their last statement, so each is live again. */
    public void unbindPerson(String sheet, long person) {
        jdbc.update("UPDATE claim SET stated = FALSE, stated_due = NULL WHERE sheet = ? AND person = ? AND stated",
                sheet, person);
    }

    /** Records the user who opened the claim. */
    public void setOpenedBy(String sheet, long id, String user) {
        jdbc.update("UPDATE claim SET opened_by = ? WHERE sheet = ? AND id = ?", user, sheet, id);
    }

    /** Sets the claim's number on the sheet, or clears it with null. */
    public void setNumber(String sheet, long id, Integer number) {
        jdbc.update("UPDATE claim SET number_on_sheet = ? WHERE sheet = ? AND id = ?", number, sheet, id);
    }

    /** Sets the claim's number within its period. */
    public void setPeriodNumber(String sheet, long id, String periodNumber) {
        jdbc.update("UPDATE claim SET period_number = ? WHERE sheet = ? AND id = ?", periodNumber, sheet, id);
    }

    /**
     * Takes the next number in the sheet's period of the name ("" for the claims in no period): 1 first, then 2,
     * and so on, each period counting on its own. Locked as {@link #nextNumber}.
     */
    public int nextPeriodNumber(String sheet, String period) {
        while (true) {
            if (jdbc.update("UPDATE claim_period_number SET last_number = last_number + 1 WHERE sheet = ? AND period = ?",
                    sheet, period) == 1) {
                return jdbc.queryForObject("SELECT last_number FROM claim_period_number WHERE sheet = ? AND period = ?",
                        Integer.class, sheet, period);
            }
            try {
                jdbc.update("INSERT INTO claim_period_number (sheet, period, last_number) VALUES (?, ?, 1)", sheet, period);
                return 1;
            } catch (DuplicateKeyException raced) {
                // Another user took the period's first number at the same moment: take the one after it.
            }
        }
    }

    /**
     * Takes the sheet's next claim number: 1 first, then 2, and so on. The counter row stays locked until the
     * transaction ends, so two claims opened at once get different numbers.
     */
    public int nextNumber(String sheet) {
        while (true) {
            if (jdbc.update("UPDATE claim_number SET last_number = last_number + 1 WHERE sheet = ?", sheet) == 1) {
                return jdbc.queryForObject("SELECT last_number FROM claim_number WHERE sheet = ?", Integer.class,
                        sheet);
            }
            try {
                jdbc.update("INSERT INTO claim_number (sheet, last_number) VALUES (?, 1)", sheet);
                return 1;
            } catch (DuplicateKeyException raced) {
                // Another user took the sheet's first number at the same moment: take the one after it.
            }
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

public class BuildClaim {
    public void build(@PathVariable("sheet") String sheet, @RequestParam("user") String user, @Val Person person,
            @Val ClaimInput input, Claims claims, Periods periods, Settings settings, ClaimLog log, Audit audit, Rollup rollup)
            throws InvalidClaimException {
        if (periods.closedOn(sheet, input.date())) {
            throw new InvalidClaimException("A claim may not be dated inside a closed period");
        }
        if (person.retiredBefore(input.date())) {
            throw new InvalidClaimException("A claim may not be dated after the person's retirement date");
        }
        input.checkCorrects(sheet, person.id(), claims);
        Rollup.Snapshot before = rollup.take(sheet);
        // The due-by is fixed now, from the terms of the person's grade in force on the claim's date, as they
        // stand on that date.
        long id = claims.add(sheet, person.id(), input, person.dueBy(sheet, input.date(), settings));
        log.record(sheet, user, id);
        audit.record("CLAIM_ADDED sheet=" + sheet + " by=" + user + " " + input.auditFields(person.name()));
        if (periods.softClosedOn(sheet, input.date())) {
            claims.setLateEntry(sheet, id);
            audit.record("LATE_ENTRY sheet=" + sheet + " by=" + user + " " + input.auditFields(person.name()));
        }
        rollup.record(sheet, user, before);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import java.time.LocalDate;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

public class SaveClaim {
    public void save(@PathVariable("sheet") String sheet, @RequestParam("user") String user, @Val Claim claim,
            @Val ClaimInput input, Claims claims, People people, Periods periods, Audit audit, Rollup rollup)
            throws InvalidClaimException {
        // A claim dated inside a closed period may not be edited, nor moved into one.
        if (periods.closedOn(sheet, LocalDate.parse(claim.date())) || periods.closedOn(sheet, input.date())) {
            throw new InvalidClaimException("A claim dated inside a closed period may not be edited");
        }
        // Only a draft may be edited: an open claim is voided and a new one added instead.
        if (claim.status() != ClaimStatus.DRAFT) {
            throw new InvalidClaimException("A " + claim.status() + " claim cannot be edited; only a DRAFT can");
        }
        Person owner = people.find(sheet, claim.person());
        if (owner.retiredBefore(input.date())) {
            throw new InvalidClaimException("A claim may not be dated after the person's retirement date");
        }
        input.checkCorrects(sheet, owner.id(), claims);
        Rollup.Snapshot before = rollup.take(sheet);
        if (claim.lockedBy() != null && !claim.lockedBy().equals(user)) {
            throw new InvalidClaimException("The claim is being edited by " + claim.lockedBy());
        }
        // Conditional on the claim still being a draft and not locked by another user's editor, so one another user
        // opened or locked meanwhile is refused; the save releases the lock.
        if (!claims.update(sheet, claim.id(), input, user)) {
            throw new InvalidClaimException("The claim is no longer a DRAFT, or another user is editing it");
        }
        audit.record("CLAIM_EDITED sheet=" + sheet + " by=" + user + " " + input.auditFields(owner.name()));
        rollup.record(sheet, user, before);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import net.officefloor.hq.app.Audit;
import java.time.LocalDate;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.Roles;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.SheetArchive;
import net.officefloor.hq.app.sheet.SheetClock;
import net.officefloor.hq.app.watch.Watches;
import org.springframework.stereotype.Service;

/** Moves a claim to the status a change takes it to, refusing a change its status does not allow; shared by a
 *  claim's own status buttons and the bulk actions. */
@Service
public class ClaimStatusChanger {

    /** How many days after its settlement a steward may still void a SETTLED claim. */
    public static final int VOID_SETTLED_DAYS = 7;

    private final Claims claims;
    private final People people;
    private final Rates rates;
    private final Periods periods;
    private final Roles roles;
    private final Settings settings;
    private final SheetClock clock;
    private final Audit audit;
    private final Rollup rollup;
    private final ClaimLog log;
    private final Watches watches;
    private final SheetArchive archive;

    public ClaimStatusChanger(Claims claims, People people, Rates rates, Periods periods, Roles roles, Settings settings,
            SheetClock clock, Audit audit, Rollup rollup, ClaimLog log, Watches watches, SheetArchive archive) {
        this.claims = claims;
        this.people = people;
        this.rates = rates;
        this.periods = periods;
        this.roles = roles;
        this.settings = settings;
        this.clock = clock;
        this.audit = audit;
        this.rollup = rollup;
        this.log = log;
        this.watches = watches;
        this.archive = archive;
    }

    /** Applies the change to the claim, writing nothing when it is refused. */
    public void change(String sheet, String user, Claim claim, ClaimStatusChange requested)
            throws InvalidClaimStatusChangeException {
        change(sheet, user, claim, requested, null);
    }

    /** Applies the change to the claim (a reject gives its reason), writing nothing when it is refused. */
    public void change(String sheet, String user, Claim claim, ClaimStatusChange requested, String reason)
            throws InvalidClaimStatusChangeException {
        // A viewer changes nothing.
        if (Role.VIEWER.equals(roles.of(sheet, user))) {
            throw new InvalidClaimStatusChangeException("A viewer cannot change a claim");
        }
        if (archive.archived(sheet)) {
            throw new InvalidClaimStatusChangeException("An archived sheet cannot change");
        }
        // The permission matrix says which roles open, settle and void a claim.
        if ((requested == ClaimStatusChange.OPEN || requested == ClaimStatusChange.SETTLE || requested == ClaimStatusChange.VOID)
                && !settings.permits(sheet, requested.name().toLowerCase(), roles.of(sheet, user))) {
            throw new InvalidClaimStatusChangeException("Your role may not " + requested.name().toLowerCase() + " a claim");
        }
        if (periods.closedOn(sheet, LocalDate.parse(claim.date()))) {
            throw new InvalidClaimStatusChangeException("A claim dated inside a closed period cannot change status");
        }
        // A steward voids a SETTLED claim only within 7 days of its settlement (its status log's last SETTLED date).
        if (requested == ClaimStatusChange.VOID && claim.status() == ClaimStatus.SETTLED) {
            if (!Role.STEWARD.equals(roles.of(sheet, user))) {
                throw new InvalidClaimStatusChangeException("Only a steward voids a settled claim");
            }
            LocalDate settled = claim.settledOn();
            LocalDate today = clock.today(sheet);
            if (settled == null || today.isBefore(settled) || today.isAfter(settled.plusDays(VOID_SETTLED_DAYS))) {
                throw new InvalidClaimStatusChangeException(
                        "A settled claim may be voided only within " + VOID_SETTLED_DAYS + " days of its settlement");
            }
        }
        if (requested == ClaimStatusChange.SETTLE && claim.deferred()) {
            throw new InvalidClaimStatusChangeException("A deferred claim cannot be settled until its date");
        }
        // Four eyes: the user who opened a claim may not settle it, nor approve it.
        if ((requested == ClaimStatusChange.SETTLE || requested == ClaimStatusChange.APPROVE)
                && user.equals(claim.openedBy())) {
            throw new InvalidClaimStatusChangeException("The user who opened a claim cannot settle or approve it");
        }
        // Only a steward approves or rejects a PENDING claim; a reject gives a reason.
        if ((requested == ClaimStatusChange.APPROVE || requested == ClaimStatusChange.REJECT)
                && !Role.STEWARD.equals(roles.of(sheet, user))) {
            throw new InvalidClaimStatusChangeException("Only a steward approves or rejects a claim");
        }
        if (requested == ClaimStatusChange.REJECT && (reason == null || reason.isBlank())) {
            throw new InvalidClaimStatusChangeException("A reject needs a reason");
        }
        Person person = people.find(sheet, claim.person());
        // A claim whose due is above the proof threshold in force on its date is settled or approved only once it has
        // a proof (a due of n/a is above no threshold); checked before the clerk limit, so it never goes to PENDING.
        if (requested == ClaimStatusChange.SETTLE || requested == ClaimStatusChange.APPROVE) {
            BigDecimal threshold = settings.proofThreshold(sheet, LocalDate.parse(claim.date()));
            if (threshold != null && claim.proofs() == 0) {
                BigDecimal due = claim.due(rates.list(sheet), person.gradeOn(claim.date()), settings.floor(sheet),
                        settings.late(sheet, clock.today(sheet)));
                if (due != null && due.compareTo(threshold) > 0) {
                    throw new InvalidClaimStatusChangeException(
                            "A claim whose due is above the proof threshold needs a proof before it is settled or approved");
                }
            }
        }
        // A claim whose due is above the note threshold in force on its date is opened only with a note (a due of n/a
        // is above no threshold).
        if (requested == ClaimStatusChange.OPEN && (claim.note() == null || claim.note().isBlank())) {
            BigDecimal threshold = settings.noteThreshold(sheet, LocalDate.parse(claim.date()));
            if (threshold != null) {
                BigDecimal due = claim.due(rates.list(sheet), person.gradeOn(claim.date()), settings.floor(sheet),
                        settings.late(sheet, clock.today(sheet)));
                if (due != null && due.compareTo(threshold) > 0) {
                    throw new InvalidClaimStatusChangeException(
                            "A claim whose due is above the note threshold needs a note before it is opened");
                }
            }
        }
        // A clerk settles only a due at or below the sheet's clerk limit (a due of n/a is within any limit); above
        // it the claim goes to PENDING for a steward to approve. A steward settles anything.
        if (requested == ClaimStatusChange.SETTLE && claim.status() == ClaimStatus.OPEN
                && Role.CLERK.equals(roles.of(sheet, user))) {
            BigDecimal limit = settings.clerkLimit(sheet);
            BigDecimal due = claim.due(rates.list(sheet), person.gradeOn(claim.date()), settings.floor(sheet),
                    settings.late(sheet, clock.today(sheet)));
            if (limit != null && due != null && due.compareTo(limit) > 0) {
                requested = ClaimStatusChange.PEND;
            }
        }
        Rollup.Snapshot before = rollup.take(sheet);
        ClaimStatus next = claim.status().after(requested);
        // Conditional on the status read, so a concurrent change by another user is refused, not overwritten.
        if (next == null || !claims.changeStatus(sheet, claim.id(), claim.status(), next)) {
            throw new InvalidClaimStatusChangeException(
                    "A " + claim.status() + " claim does not allow " + requested.name().toLowerCase());
        }
        // Opening gives the sheet's next number, or, while the sheet numbers by period from on or before its today,
        // the next number in the claim's period (X for none); a voided claim keeps the number it had (never reused).
        Claim changed = claim;
        if (requested == ClaimStatusChange.OPEN) {
