1	package net.officefloor.hq.app.claim;
2	
3	import java.math.BigDecimal;
4	import java.math.RoundingMode;
5	import java.sql.Date;
6	import java.time.LocalDate;
7	import java.util.ArrayList;
8	import java.util.HashMap;
9	import java.util.List;
10	import java.util.Map;
11	import org.springframework.dao.DuplicateKeyException;
12	import org.springframework.jdbc.core.JdbcTemplate;
13	import org.springframework.jdbc.core.RowMapper;
14	import org.springframework.jdbc.support.GeneratedKeyHolder;
15	import org.springframework.stereotype.Repository;
16	
17	/** The claims kept per sheet, each belonging to a person on that sheet. */
18	@Repository
19	public class Claims {
20	
21	    private static final RowMapper<Claim> ROW = (rs, i) -> new Claim(rs.getLong("id"), rs.getLong("person"),
22	            rs.getBigDecimal("amount").setScale(2, RoundingMode.UNNECESSARY).toPlainString(),
23	            rs.getDate("claimed_on").toLocalDate().toString(), rs.getString("note"),
24	            ClaimStatus.valueOf(rs.getString("status")), rs.getObject("number_on_sheet", Integer.class),
25	            rs.getBigDecimal("settled_due") == null ? null
26	                    : rs.getBigDecimal("settled_due").setScale(2, RoundingMode.UNNECESSARY).toPlainString(),
27	            rs.getString("opened_by"), rs.getBoolean("stated"),
28	            rs.getBigDecimal("stated_due") == null ? null
29	                    : rs.getBigDecimal("stated_due").setScale(2, RoundingMode.UNNECESSARY).toPlainString(),
30	            rs.getString("corrects"), rs.getDate("rounds_on").toLocalDate().toString(),
31	            rs.getString("period_number"), rs.getDate("due_by").toLocalDate().toString(), List.of(),
32	            rs.getDate("deferred_until") == null ? null : rs.getDate("deferred_until").toLocalDate().toString(),
33	            rs.getBoolean("deferred"), rs.getInt("proofs"), rs.getString("split_from"),
34	            rs.getString("locked_by"), rs.getBoolean("late_entry"));
35	
36	    // A claim rounds on its own date; a correction on the date of the claim it corrects (its own when none has it).
37	    // It is deferred while OPEN with its deferred-until after the sheet's today (the real date until one is set).
38	    private static final String COLUMNS = "SELECT claim.id, claim.person, claim.amount, claim.claimed_on, claim.note, claim.status,"
39	            + " claim.number_on_sheet, claim.settled_due, claim.opened_by, claim.stated, claim.stated_due, claim.corrects,"
40	            + " claim.period_number, claim.due_by, COALESCE(corrected.claimed_on, claim.claimed_on) AS rounds_on,"
41	            + " claim.deferred_until, claim.proofs, claim.split_from, claim.locked_by, claim.late_entry, (claim.status = 'OPEN' AND claim.deferred_until IS NOT NULL AND claim.deferred_until >"
42	            + " COALESCE((SELECT s.today FROM sheet s WHERE s.id = claim.sheet), CURRENT_DATE)) AS deferred FROM claim"
43	            + " LEFT JOIN claim corrected ON corrected.sheet = claim.sheet AND "
44	            + " COALESCE(corrected.period_number, CAST(corrected.number_on_sheet AS VARCHAR)) = claim.corrects";
45	
46	    // The place after every claim listed on the sheet (bound to the sheet), so the claim lists newest.
47	    private static final String NEXT_LISTED = "(SELECT COALESCE(MAX(l.listed), 0) + 1 FROM claim l WHERE l.sheet = ?)";
48	
49	    private final JdbcTemplate jdbc;
50	
51	    public Claims(JdbcTemplate jdbc) {
52	        this.jdbc = jdbc;
53	    }
54	
55	    private static final String LOG = "SELECT claim, status, by_user, on_date, due FROM claim_log WHERE sheet = ?";
56	
57	    /** Every claim on the sheet, newest first. */
58	    public List<Claim> list(String sheet) {
59	        return withLogs(sheet, jdbc.query(COLUMNS + " WHERE claim.sheet = ? ORDER BY claim.listed DESC, claim.id DESC", ROW, sheet),
60	                jdbc.query(LOG + " ORDER BY id", LOG_ROW, sheet));
61	    }
62	
63	    public Claim find(String sheet, long id) {
64	        List<Claim> found = jdbc.query(COLUMNS + " WHERE claim.sheet = ? AND claim.id = ?", ROW, sheet, id);
65	        return found.isEmpty() ? null
66	                : withLogs(sheet, found, jdbc.query(LOG + " AND claim = ? ORDER BY id", LOG_ROW, sheet, id)).get(0);
67	    }
68	
69	    private record Logged(long claim, ClaimLogLine line) {
70	    }
71	
72	    private static final RowMapper<Logged> LOG_ROW = (rs, i) -> new Logged(rs.getLong("claim"),
73	            new ClaimLogLine(ClaimStatus.valueOf(rs.getString("status")), rs.getString("by_user"),
74	                    rs.getDate("on_date").toLocalDate().toString(), rs.getString("due")));
75	
76	    /** The claims, each with its own lines of the status log (oldest first). */
77	    private static List<Claim> withLogs(String sheet, List<Claim> found, List<Logged> logged) {
78	        Map<Long, List<ClaimLogLine>> lines = new HashMap<>();
79	        for (Logged l : logged) {
80	            lines.computeIfAbsent(l.claim(), k -> new ArrayList<>()).add(l.line());
81	        }
82	        return found.stream().map(c -> c.withLog(lines.getOrDefault(c.id(), List.of()))).toList();
83	    }
84	
85	    /** The claim showing this number on the sheet (within its period, or on the sheet), or null when none does. */
86	    public Claim findByNumber(String sheet, String number) {
87	        List<Claim> found = jdbc.query(COLUMNS + " WHERE claim.sheet = ?"
88	                + " AND COALESCE(claim.period_number, CAST(claim.number_on_sheet AS VARCHAR)) = ?", ROW, sheet, number);
89	        return found.isEmpty() ? null : found.get(0);
90	    }
91	
92	    /** Adds the claim with its due-by, fixed now and never moved after; returns its id. */
93	    public long add(String sheet, long person, ClaimInput input, LocalDate dueBy) {
94	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
95	        jdbc.update(con -> {
96	            var ps = con.prepareStatement("INSERT INTO claim (sheet, person, amount, claimed_on, note, corrects, due_by, listed)"
97	                    + " VALUES (?, ?, ?, ?, ?, ?, ?, " + NEXT_LISTED + ")", new String[] { "id" });
98	            ps.setString(1, sheet);
99	            ps.setLong(2, person);
100	            ps.setBigDecimal(3, input.amount());
101	            ps.setDate(4, Date.valueOf(input.date()));
102	            ps.setString(5, input.note());
103	            ps.setString(6, input.corrects());
104	            ps.setDate(7, Date.valueOf(dueBy));
105	            ps.setString(8, sheet);
106	            return ps;
107	        }, keys);
108	        return keys.getKey().longValue();
109	    }
110	
111	    /** Marks the claim a late entry: added while the period its date falls in was soft-closed. */
112	    public void setLateEntry(String sheet, long id) {
113	        jdbc.update("UPDATE claim SET late_entry = TRUE WHERE sheet = ? AND id = ?", sheet, id);
114	    }
115	
116	    /**
117	     * Adds the OPEN claim split off another: the amount, with the date and note of the claim it was split from (by
118	     * the number that claim shows), opened by the user, with its due-by fixed now; returns its id.
119	     */
120	    public long addSplit(String sheet, long person, BigDecimal amount, LocalDate date, String note, LocalDate dueBy,
121	            String splitFrom, String openedBy) {
122	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
123	        jdbc.update(con -> {
124	            var ps = con.prepareStatement("INSERT INTO claim (sheet, person, amount, claimed_on, note, due_by, status,"
125	                    + " split_from, opened_by, listed) VALUES (?, ?, ?, ?, ?, ?, 'OPEN', ?, ?, " + NEXT_LISTED + ")",
126	                    new String[] { "id" });
127	            ps.setString(1, sheet);
128	            ps.setLong(2, person);
129	            ps.setBigDecimal(3, amount);
130	            ps.setDate(4, Date.valueOf(date));
131	            ps.setString(5, note);
132	            ps.setDate(6, Date.valueOf(dueBy));
133	            ps.setString(7, splitFrom);
134	            ps.setString(8, openedBy);
135	            ps.setString(9, sheet);
136	            return ps;
137	        }, keys);
138	        return keys.getKey().longValue();
139	    }
140	
141	    /**
142	     * Leaves an OPEN claim the rest of its amount once split, unbound from any statement; conditional on the
143	     * amount read and on it still being OPEN and not deferred: false when it no longer is.
144	     */
145	    public boolean split(String sheet, long id, BigDecimal was, BigDecimal rest) {
146	        return jdbc.update("UPDATE claim SET amount = ?, stated = FALSE, stated_due = NULL WHERE sheet = ? AND id = ?"
147	                + " AND status = 'OPEN' AND amount = ? AND (deferred_until IS NULL OR deferred_until <="
148	                + " COALESCE((SELECT s.today FROM sheet s WHERE s.id = claim.sheet), CURRENT_DATE))",
149	                rest, sheet, id, was) == 1;
150	    }
151	
152	    /**
153	     * Edits a draft claim not locked by another user's editor, releasing any lock on it: false when it is no longer a
154	     * draft, or another user's editor holds it.
155	     */
156	    public boolean update(String sheet, long id, ClaimInput input, String user) {
157	        return jdbc.update(
158	                "UPDATE claim SET amount = ?, claimed_on = ?, note = ?, corrects = ?, locked_by = NULL WHERE sheet = ? AND id = ?"
159	                        + " AND status = 'DRAFT' AND (locked_by IS NULL OR locked_by = ?)",
160	                input.amount(), Date.valueOf(input.date()), input.note(), input.corrects(), sheet, id, user) == 1;
161	    }
162	
163	    /**
164	     * Locks a draft claim for the user's editor, releasing any other claim the user's editor held on the sheet:
165	     * false when it is no longer a draft, or another user's editor holds it.
166	     */
167	    public boolean lock(String sheet, long id, String user) {
168	        if (jdbc.update("UPDATE claim SET locked_by = ? WHERE sheet = ? AND id = ? AND status = 'DRAFT'"
169	                + " AND (locked_by IS NULL OR locked_by = ?)", user, sheet, id, user) != 1) {
170	            return false;
171	        }
172	        jdbc.update("UPDATE claim SET locked_by = NULL WHERE sheet = ? AND id <> ? AND locked_by = ?", sheet, id, user);
173	        return true;
174	    }
175	
176	    /** Releases the claim's lock when the user's editor holds it. */
177	    public void unlock(String sheet, long id, String user) {
178	        jdbc.update("UPDATE claim SET locked_by = NULL WHERE sheet = ? AND id = ? AND locked_by = ?", sheet, id, user);
179	    }
180	
181	    /** Releases every lock on the sheet's claims, as when its today changes. */
182	    public void unlockAll(String sheet) {
183	        jdbc.update("UPDATE claim SET locked_by = NULL WHERE sheet = ? AND locked_by IS NOT NULL", sheet);
184	    }
185	
186	    /**
187	     * Moves the claim of the person and status it was read with to another person, unbound from any statement and
188	     * listed as the sheet's newest: false when it no longer has that person or status.
189	     */
190	    public boolean reassign(String sheet, long id, long from, ClaimStatus status, long to) {
191	        return jdbc.update("UPDATE claim SET person = ?, stated = FALSE, stated_due = NULL, listed = " + NEXT_LISTED
192	                + " WHERE sheet = ? AND id = ? AND person = ? AND status = ?", to, sheet, sheet, id, from,
193	                status.name()) == 1;
194	    }
195	
196	    /**
197	     * Moves the claim of the status and date it was read with to another date, keeping its due-by and any figure its
198	     * statement bound: false when it no longer has that status or date.
199	     */
200	    public boolean redate(String sheet, long id, ClaimStatus status, LocalDate was, LocalDate date) {
201	        return jdbc.update("UPDATE claim SET claimed_on = ? WHERE sheet = ? AND id = ? AND status = ? AND claimed_on = ?",
202	                Date.valueOf(date), sheet, id, status.name(), Date.valueOf(was)) == 1;
203	    }
204	
205	    /** Moves the claim from one status to another: false when it no longer has the status it was read with. */
206	    public boolean changeStatus(String sheet, long id, ClaimStatus from, ClaimStatus to) {
207	        return jdbc.update("UPDATE claim SET status = ? WHERE sheet = ? AND id = ? AND status = ?", to.name(), sheet,
208	                id, from.name()) == 1;
209	    }
210	
211	    /** Defers an OPEN claim until the date: false when it is no longer OPEN. */
212	    public boolean defer(String sheet, long id, LocalDate until) {
213	        return jdbc.update("UPDATE claim SET deferred_until = ? WHERE sheet = ? AND id = ? AND status = 'OPEN'",
214	                Date.valueOf(until), sheet, id) == 1;
215	    }
216	
217	    /**
218	     * Raises the claim's proofs count by one, conditional on the status and count read, so a concurrent change by
219	     * another user is refused, not overwritten: false when it was not.
220	     */
221	    public boolean addProof(String sheet, long id, ClaimStatus status, int was) {
222	        return jdbc.update("UPDATE claim SET proofs = proofs + 1 WHERE sheet = ? AND id = ? AND status = ? AND proofs = ?",
223	                sheet, id, status.name(), was) == 1;
224	    }
225	
226	    /** Fixes the claim's due as it is settled, or leaves none with null. */
227	    public void setSettledDue(String sheet, long id, BigDecimal due) {
228	        jdbc.update("UPDATE claim SET settled_due = ? WHERE sheet = ? AND id = ?", due, sheet, id);
229	    }
230	
231	    /**
232	     * Re-fixes a SETTLED claim's due (null for none), conditional on the due read, so a concurrent change by another
233	     * user is refused, not overwritten; false when it was not.
234	     */
235	    public boolean resettle(String sheet, long id, BigDecimal was, BigDecimal due) {
236	        return jdbc.update("UPDATE claim SET settled_due = ? WHERE sheet = ? AND id = ? AND status = ?"
237	                + " AND settled_due IS NOT DISTINCT FROM ?", due, sheet, id, ClaimStatus.SETTLED.name(), was) == 1;
238	    }
239	
240	    /** Binds the claim to a statement's figure (null when its grade had no rate), or unbinds it when not stated. */
241	    public void setStated(String sheet, long id, boolean stated, BigDecimal due) {
242	        jdbc.update("UPDATE claim SET stated = ?, stated_due = ? WHERE sheet = ? AND id = ?", stated, due, sheet, id);
243	    }
244	
245	    /** Unbinds every claim of the person bound by their last statement, so each is live again. */
246	    public void unbindPerson(String sheet, long person) {
247	        jdbc.update("UPDATE claim SET stated = FALSE, stated_due = NULL WHERE sheet = ? AND person = ? AND stated",
248	                sheet, person);
249	    }
250	
251	    /** Records the user who opened the claim. */
252	    public void setOpenedBy(String sheet, long id, String user) {
253	        jdbc.update("UPDATE claim SET opened_by = ? WHERE sheet = ? AND id = ?", user, sheet, id);
254	    }
255	
256	    /** Sets the claim's number on the sheet, or clears it with null. */
257	    public void setNumber(String sheet, long id, Integer number) {
258	        jdbc.update("UPDATE claim SET number_on_sheet = ? WHERE sheet = ? AND id = ?", number, sheet, id);
259	    }
260	
261	    /** Sets the claim's number within its period. */
262	    public void setPeriodNumber(String sheet, long id, String periodNumber) {
263	        jdbc.update("UPDATE claim SET period_number = ? WHERE sheet = ? AND id = ?", periodNumber, sheet, id);
264	    }
265	
266	    /**
267	     * Takes the next number in the sheet's period of the name ("" for the claims in no period): 1 first, then 2,
268	     * and so on, each period counting on its own. Locked as {@link #nextNumber}.
269	     */
270	    public int nextPeriodNumber(String sheet, String period) {
271	        while (true) {
272	            if (jdbc.update("UPDATE claim_period_number SET last_number = last_number + 1 WHERE sheet = ? AND period = ?",
273	                    sheet, period) == 1) {
274	                return jdbc.queryForObject("SELECT last_number FROM claim_period_number WHERE sheet = ? AND period = ?",
275	                        Integer.class, sheet, period);
276	            }
277	            try {
278	                jdbc.update("INSERT INTO claim_period_number (sheet, period, last_number) VALUES (?, ?, 1)", sheet, period);
279	                return 1;
280	            } catch (DuplicateKeyException raced) {
281	                // Another user took the period's first number at the same moment: take the one after it.
282	            }
283	        }
284	    }
285	
286	    /**
287	     * Takes the sheet's next claim number: 1 first, then 2, and so on. The counter row stays locked until the
288	     * transaction ends, so two claims opened at once get different numbers.
289	     */
290	    public int nextNumber(String sheet) {
291	        while (true) {
292	            if (jdbc.update("UPDATE claim_number SET last_number = last_number + 1 WHERE sheet = ?", sheet) == 1) {
293	                return jdbc.queryForObject("SELECT last_number FROM claim_number WHERE sheet = ?", Integer.class,
294	                        sheet);
295	            }
296	            try {
297	                jdbc.update("INSERT INTO claim_number (sheet, last_number) VALUES (?, 1)", sheet);
298	                return 1;
299	            } catch (DuplicateKeyException raced) {
300	                // Another user took the sheet's first number at the same moment: take the one after it.
301	            }
302	        }
303	    }
304	}
