307	import net.officefloor.hq.app.Audit;
308	import net.officefloor.hq.app.period.Periods;
309	import net.officefloor.hq.app.person.Person;
310	import net.officefloor.hq.app.rollup.Rollup;
311	import net.officefloor.hq.app.setting.Settings;
312	import net.officefloor.plugin.variable.Val;
313	import org.springframework.web.bind.annotation.PathVariable;
314	import org.springframework.web.bind.annotation.RequestParam;
315	
316	public class BuildClaim {
317	    public void build(@PathVariable("sheet") String sheet, @RequestParam("user") String user, @Val Person person,
318	            @Val ClaimInput input, Claims claims, Periods periods, Settings settings, ClaimLog log, Audit audit, Rollup rollup)
319	            throws InvalidClaimException {
320	        if (periods.closedOn(sheet, input.date())) {
321	            throw new InvalidClaimException("A claim may not be dated inside a closed period");
322	        }
323	        if (person.retiredBefore(input.date())) {
324	            throw new InvalidClaimException("A claim may not be dated after the person's retirement date");
325	        }
326	        input.checkCorrects(sheet, person.id(), claims);
327	        Rollup.Snapshot before = rollup.take(sheet);
328	        // The due-by is fixed now, from the terms of the person's grade in force on the claim's date, as they
329	        // stand on that date.
330	        long id = claims.add(sheet, person.id(), input, person.dueBy(sheet, input.date(), settings));
331	        log.record(sheet, user, id);
332	        audit.record("CLAIM_ADDED sheet=" + sheet + " by=" + user + " " + input.auditFields(person.name()));
333	        if (periods.softClosedOn(sheet, input.date())) {
334	            claims.setLateEntry(sheet, id);
335	            audit.record("LATE_ENTRY sheet=" + sheet + " by=" + user + " " + input.auditFields(person.name()));
336	        }
337	        rollup.record(sheet, user, before);
338	    }
339	}
340	package net.officefloor.hq.app.claim;
341	
342	import net.officefloor.hq.app.Audit;
343	import java.time.LocalDate;
344	import net.officefloor.hq.app.period.Periods;
345	import net.officefloor.hq.app.person.People;
346	import net.officefloor.hq.app.person.Person;
347	import net.officefloor.hq.app.rollup.Rollup;
348	import net.officefloor.plugin.variable.Val;
349	import org.springframework.web.bind.annotation.PathVariable;
350	import org.springframework.web.bind.annotation.RequestParam;
351	
352	public class SaveClaim {
353	    public void save(@PathVariable("sheet") String sheet, @RequestParam("user") String user, @Val Claim claim,
354	            @Val ClaimInput input, Claims claims, People people, Periods periods, Audit audit, Rollup rollup)
355	            throws InvalidClaimException {
356	        // A claim dated inside a closed period may not be edited, nor moved into one.
357	        if (periods.closedOn(sheet, LocalDate.parse(claim.date())) || periods.closedOn(sheet, input.date())) {
358	            throw new InvalidClaimException("A claim dated inside a closed period may not be edited");
359	        }
360	        // Only a draft may be edited: an open claim is voided and a new one added instead.
361	        if (claim.status() != ClaimStatus.DRAFT) {
362	            throw new InvalidClaimException("A " + claim.status() + " claim cannot be edited; only a DRAFT can");
363	        }
364	        Person owner = people.find(sheet, claim.person());
365	        if (owner.retiredBefore(input.date())) {
366	            throw new InvalidClaimException("A claim may not be dated after the person's retirement date");
367	        }
368	        input.checkCorrects(sheet, owner.id(), claims);
369	        Rollup.Snapshot before = rollup.take(sheet);
370	        if (claim.lockedBy() != null && !claim.lockedBy().equals(user)) {
371	            throw new InvalidClaimException("The claim is being edited by " + claim.lockedBy());
372	        }
373	        // Conditional on the claim still being a draft and not locked by another user's editor, so one another user
374	        // opened or locked meanwhile is refused; the save releases the lock.
375	        if (!claims.update(sheet, claim.id(), input, user)) {
376	            throw new InvalidClaimException("The claim is no longer a DRAFT, or another user is editing it");
377	        }
378	        audit.record("CLAIM_EDITED sheet=" + sheet + " by=" + user + " " + input.auditFields(owner.name()));
379	        rollup.record(sheet, user, before);
380	    }
381	}
