385	import net.officefloor.hq.app.Audit;
386	import java.time.LocalDate;
387	import net.officefloor.hq.app.period.Periods;
388	import net.officefloor.hq.app.person.People;
389	import net.officefloor.hq.app.person.Person;
390	import net.officefloor.hq.app.rate.Rates;
391	import net.officefloor.hq.app.role.Role;
392	import net.officefloor.hq.app.role.Roles;
393	import net.officefloor.hq.app.rollup.Rollup;
394	import net.officefloor.hq.app.setting.Settings;
395	import net.officefloor.hq.app.sheet.SheetArchive;
396	import net.officefloor.hq.app.sheet.SheetClock;
397	import net.officefloor.hq.app.watch.Watches;
398	import org.springframework.stereotype.Service;
399	
400	/** Moves a claim to the status a change takes it to, refusing a change its status does not allow; shared by a
401	 *  claim's own status buttons and the bulk actions. */
402	@Service
403	public class ClaimStatusChanger {
404	
405	    /** How many days after its settlement a steward may still void a SETTLED claim. */
406	    public static final int VOID_SETTLED_DAYS = 7;
407	
408	    private final Claims claims;
409	    private final People people;
410	    private final Rates rates;
411	    private final Periods periods;
412	    private final Roles roles;
413	    private final Settings settings;
414	    private final SheetClock clock;
415	    private final Audit audit;
416	    private final Rollup rollup;
417	    private final ClaimLog log;
418	    private final Watches watches;
419	    private final SheetArchive archive;
420	
421	    public ClaimStatusChanger(Claims claims, People people, Rates rates, Periods periods, Roles roles, Settings settings,
422	            SheetClock clock, Audit audit, Rollup rollup, ClaimLog log, Watches watches, SheetArchive archive) {
423	        this.claims = claims;
424	        this.people = people;
425	        this.rates = rates;
426	        this.periods = periods;
427	        this.roles = roles;
428	        this.settings = settings;
429	        this.clock = clock;
430	        this.audit = audit;
431	        this.rollup = rollup;
432	        this.log = log;
433	        this.watches = watches;
434	        this.archive = archive;
435	    }
436	
437	    /** Applies the change to the claim, writing nothing when it is refused. */
438	    public void change(String sheet, String user, Claim claim, ClaimStatusChange requested)
439	            throws InvalidClaimStatusChangeException {
440	        change(sheet, user, claim, requested, null);
441	    }
442	
443	    /** Applies the change to the claim (a reject gives its reason), writing nothing when it is refused. */
444	    public void change(String sheet, String user, Claim claim, ClaimStatusChange requested, String reason)
445	            throws InvalidClaimStatusChangeException {
446	        // A viewer changes nothing.
447	        if (Role.VIEWER.equals(roles.of(sheet, user))) {
448	            throw new InvalidClaimStatusChangeException("A viewer cannot change a claim");
449	        }
450	        if (archive.archived(sheet)) {
451	            throw new InvalidClaimStatusChangeException("An archived sheet cannot change");
452	        }
453	        // The permission matrix says which roles open, settle and void a claim.
454	        if ((requested == ClaimStatusChange.OPEN || requested == ClaimStatusChange.SETTLE || requested == ClaimStatusChange.VOID)
455	                && !settings.permits(sheet, requested.name().toLowerCase(), roles.of(sheet, user))) {
456	            throw new InvalidClaimStatusChangeException("Your role may not " + requested.name().toLowerCase() + " a claim");
457	        }
458	        if (periods.closedOn(sheet, LocalDate.parse(claim.date()))) {
459	            throw new InvalidClaimStatusChangeException("A claim dated inside a closed period cannot change status");
460	        }
461	        // A steward voids a SETTLED claim only within 7 days of its settlement (its status log's last SETTLED date).
462	        if (requested == ClaimStatusChange.VOID && claim.status() == ClaimStatus.SETTLED) {
463	            if (!Role.STEWARD.equals(roles.of(sheet, user))) {
464	                throw new InvalidClaimStatusChangeException("Only a steward voids a settled claim");
465	            }
466	            LocalDate settled = claim.settledOn();
467	            LocalDate today = clock.today(sheet);
468	            if (settled == null || today.isBefore(settled) || today.isAfter(settled.plusDays(VOID_SETTLED_DAYS))) {
469	                throw new InvalidClaimStatusChangeException(
470	                        "A settled claim may be voided only within " + VOID_SETTLED_DAYS + " days of its settlement");
471	            }
472	        }
473	        if (requested == ClaimStatusChange.SETTLE && claim.deferred()) {
474	            throw new InvalidClaimStatusChangeException("A deferred claim cannot be settled until its date");
475	        }
476	        // Four eyes: the user who opened a claim may not settle it, nor approve it.
477	        if ((requested == ClaimStatusChange.SETTLE || requested == ClaimStatusChange.APPROVE)
478	                && user.equals(claim.openedBy())) {
479	            throw new InvalidClaimStatusChangeException("The user who opened a claim cannot settle or approve it");
480	        }
481	        // Only a steward approves or rejects a PENDING claim; a reject gives a reason.
482	        if ((requested == ClaimStatusChange.APPROVE || requested == ClaimStatusChange.REJECT)
483	                && !Role.STEWARD.equals(roles.of(sheet, user))) {
484	            throw new InvalidClaimStatusChangeException("Only a steward approves or rejects a claim");
485	        }
486	        if (requested == ClaimStatusChange.REJECT && (reason == null || reason.isBlank())) {
487	            throw new InvalidClaimStatusChangeException("A reject needs a reason");
488	        }
489	        Person person = people.find(sheet, claim.person());
490	        // A claim whose due is above the proof threshold in force on its date is settled or approved only once it has
491	        // a proof (a due of n/a is above no threshold); checked before the clerk limit, so it never goes to PENDING.
492	        if (requested == ClaimStatusChange.SETTLE || requested == ClaimStatusChange.APPROVE) {
493	            BigDecimal threshold = settings.proofThreshold(sheet, LocalDate.parse(claim.date()));
494	            if (threshold != null && claim.proofs() == 0) {
495	                BigDecimal due = claim.due(rates.list(sheet), person.gradeOn(claim.date()), settings.floor(sheet),
496	                        settings.late(sheet, clock.today(sheet)));
497	                if (due != null && due.compareTo(threshold) > 0) {
498	                    throw new InvalidClaimStatusChangeException(
499	                            "A claim whose due is above the proof threshold needs a proof before it is settled or approved");
500	                }
501	            }
502	        }
503	        // A claim whose due is above the note threshold in force on its date is opened only with a note (a due of n/a
504	        // is above no threshold).
505	        if (requested == ClaimStatusChange.OPEN && (claim.note() == null || claim.note().isBlank())) {
506	            BigDecimal threshold = settings.noteThreshold(sheet, LocalDate.parse(claim.date()));
507	            if (threshold != null) {
508	                BigDecimal due = claim.due(rates.list(sheet), person.gradeOn(claim.date()), settings.floor(sheet),
509	                        settings.late(sheet, clock.today(sheet)));
510	                if (due != null && due.compareTo(threshold) > 0) {
511	                    throw new InvalidClaimStatusChangeException(
512	                            "A claim whose due is above the note threshold needs a note before it is opened");
513	                }
514	            }
515	        }
516	        // A clerk settles only a due at or below the sheet's clerk limit (a due of n/a is within any limit); above
517	        // it the claim goes to PENDING for a steward to approve. A steward settles anything.
518	        if (requested == ClaimStatusChange.SETTLE && claim.status() == ClaimStatus.OPEN
519	                && Role.CLERK.equals(roles.of(sheet, user))) {
520	            BigDecimal limit = settings.clerkLimit(sheet);
521	            BigDecimal due = claim.due(rates.list(sheet), person.gradeOn(claim.date()), settings.floor(sheet),
522	                    settings.late(sheet, clock.today(sheet)));
523	            if (limit != null && due != null && due.compareTo(limit) > 0) {
524	                requested = ClaimStatusChange.PEND;
525	            }
526	        }
527	        Rollup.Snapshot before = rollup.take(sheet);
528	        ClaimStatus next = claim.status().after(requested);
529	        // Conditional on the status read, so a concurrent change by another user is refused, not overwritten.
530	        if (next == null || !claims.changeStatus(sheet, claim.id(), claim.status(), next)) {
531	            throw new InvalidClaimStatusChangeException(
532	                    "A " + claim.status() + " claim does not allow " + requested.name().toLowerCase());
533	        }
534	        // Opening gives the sheet's next number, or, while the sheet numbers by period from on or before its today,
535	        // the next number in the claim's period (X for none); a voided claim keeps the number it had (never reused).
536	        Claim changed = claim;
537	        if (requested == ClaimStatusChange.OPEN) {
538	            changed = number(sheet, claim);
539	            claims.setOpenedBy(sheet, claim.id(), user);
540	        }
541	        String fields = changed.statusAuditFields(person.name());
542	        // Settling (or approving a PENDING claim, its live figure then) fixes the due at the person's grade rate in force on the claim's date (or the figure its
543	        // statement bound), with its late charge frozen in; with no rate there is nothing to fix, so it stays live.
544	        if (requested == ClaimStatusChange.SETTLE || requested == ClaimStatusChange.APPROVE) {
545	            BigDecimal due = claim.due(rates.list(sheet), person.gradeOn(claim.date()), settings.floor(sheet),
546	                    settings.late(sheet, clock.today(sheet)));
547	            claims.setSettledDue(sheet, claim.id(), due);
548	            fields += " due=" + (due == null ? "n/a" : due.toPlainString());
549	        }
550	        // Voiding a SETTLED claim reverses its frozen figure out of every total.
551	        if (requested == ClaimStatusChange.VOID && claim.status() == ClaimStatus.SETTLED) {
552	            fields += " reversed=" + (claim.settledDue() == null ? "n/a" : claim.settledDue());
553	        }
554	        if (requested == ClaimStatusChange.REJECT) {
555	            fields += " reason=" + reason.trim();
556	        }
557	        log.record(sheet, user, claim.id());
558	        audit.record(requested.event() + " sheet=" + sheet + " by=" + user + " " + fields);
559	        // Settling or approving tells each user watching the person, before the rollup lines.
560	        if (requested == ClaimStatusChange.SETTLE || requested == ClaimStatusChange.APPROVE) {
561	            watches.notify(sheet, user, person.id(), person.name(), changed.shownNumber());
562	        }
563	        rollup.record(sheet, user, before);
564	    }
565	
566	    /**
567	     * Gives an opening claim the sheet's next number, or, while the sheet numbers by period from on or before its
568	     * today, the next number in the claim's period (X for none); returns the claim so numbered.
569	     */
570	    public Claim number(String sheet, Claim claim) {
571	        LocalDate from = settings.periodNumberingFrom(sheet);
572	        if (from != null && !clock.today(sheet).isBefore(from)) {
573	            String period = periods.nameOn(sheet, LocalDate.parse(claim.date()));
574	            String key = period == null ? "" : period;
575	            Claim numbered = claim.withPeriodNumber((period == null ? "X" : period) + "-" + claims.nextPeriodNumber(sheet, key));
576	            claims.setPeriodNumber(sheet, claim.id(), numbered.periodNumber());
577	            return numbered;
578	        }
579	        Claim numbered = claim.withNumber(claims.nextNumber(sheet));
580	        claims.setNumber(sheet, claim.id(), numbered.number());
581	        return numbered;
582	    }
583	}
