package net.officefloor.hq.app.paste;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;
import net.officefloor.hq.app.claim.ClaimInput;
import net.officefloor.hq.app.claim.InvalidClaimException;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * Checks every pasted line (name,amount,date,note; the note may hold commas, the date may be blank for the sheet's entry
 * date or today, the note may be absent) by the claim form's rules before anything is written, so a refused paste adds
 * nothing. The name must be on the sheet (ignoring case). A paste carries no corrected number, so a negative amount
 * is refused as on the form without one. Blank lines are skipped; a paste with no line is refused.
 */
public class ValidatePaste {
    private static final Pattern AMOUNT = Pattern.compile("-?\\d+(\\.\\d{1,2})?");

    public void validate(@PathVariable("sheet") String sheet, @RequestBody PasteRequest request, People people,
            Settings settings, Periods periods, Out<PastedClaims> pasted) throws InvalidClaimException {
        String text = request == null || request.text() == null ? "" : request.text();
        List<PastedClaim> lines = new ArrayList<>();
        int at = 0;
        for (String line : text.split("\\r?\\n")) {
            at++;
            if (line.isBlank()) {
                continue;
            }
            lines.add(check(sheet, at, line, people, settings, periods));
        }
        if (lines.isEmpty()) {
            throw new InvalidClaimException("Paste at least one line of name,amount,date,note");
        }
        pasted.set(new PastedClaims(lines));
    }

    private static PastedClaim check(String sheet, int at, String line, People people, Settings settings,
            Periods periods) throws InvalidClaimException {
        String[] fields = line.split(",", 4);
        String name = fields[0].trim();
        String amount = fields.length > 1 ? fields[1].trim() : "";
        String date = fields.length > 2 ? fields[2].trim() : "";
        String note = fields.length > 3 ? fields[3].trim() : "";
        Person person = name.isEmpty() ? null : people.findByName(sheet, name);
        if (person == null) {
            throw new InvalidClaimException("Line " + at + ": no one named " + name + " is on the sheet");
        }
        if (!AMOUNT.matcher(amount).matches()) {
            throw new InvalidClaimException("Line " + at + ": the amount must be a number with up to two decimals");
        }
        BigDecimal value = new BigDecimal(amount);
        if (value.signum() < 0) {
            throw new InvalidClaimException("Line " + at + ": a negative amount must name the claim it corrects");
        }
        LocalDate on;
        try {
            on = date.isEmpty() ? settings.entryDay(sheet) : LocalDate.parse(date);
        } catch (DateTimeParseException e) {
            throw new InvalidClaimException("Line " + at + ": not a valid date: " + date);
        }
        if (periods.closedOn(sheet, on)) {
            throw new InvalidClaimException("Line " + at + ": a claim may not be dated inside a closed period");
        }
        if (person.retiredBefore(on)) {
            throw new InvalidClaimException(
                    "Line " + at + ": a claim may not be dated after the person's retirement date");
        }
        return new PastedClaim(person, new ClaimInput(value, on, note));
    }
}
package net.officefloor.hq.app.paste;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.ClaimInput;
import net.officefloor.hq.app.claim.ClaimLog;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** Adds a draft claim per checked line, in order, as the claim form's BuildClaim adds one. */
public class AddPastedClaims {
    public void add(@PathVariable("sheet") String sheet, @RequestParam("user") String user,
            @Val PastedClaims pasted, Claims claims, Periods periods, Settings settings, ClaimLog log, Audit audit, Rollup rollup,
            ObjectResponse<PasteResponse> response) {
        for (PastedClaim line : pasted.lines()) {
            Person person = line.person();
            ClaimInput input = line.input();
            Rollup.Snapshot before = rollup.take(sheet);
            long id = claims.add(sheet, person.id(), input, person.dueBy(sheet, input.date(), settings));
            log.record(sheet, user, id);
            audit.record("CLAIM_ADDED sheet=" + sheet + " by=" + user + " " + input.auditFields(person.name()));
            if (periods.softClosedOn(sheet, input.date())) {
                claims.setLateEntry(sheet, id);
                audit.record("LATE_ENTRY sheet=" + sheet + " by=" + user + " " + input.auditFields(person.name()));
            }
            rollup.record(sheet, user, before);
        }
        response.send(new PasteResponse(pasted.lines().size(), claims.list(sheet)));
    }
}
package net.officefloor.hq.app.quickadd;

import java.math.BigDecimal;
import java.util.regex.Pattern;
import net.officefloor.hq.app.claim.ClaimInput;
import net.officefloor.hq.app.claim.InvalidClaimException;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.InvalidPersonException;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * Checks every rule of the person and claim forms before anything is written, so a refused quick-add
 * leaves no new person behind and writes nothing to the audit file. The claim is a draft dated the
 * sheet's entry date (none set: its today) with an empty note.
 */
public class ValidateQuickAdd {
    private static final Pattern AMOUNT = Pattern.compile("\\d+(\\.\\d{1,2})?");

    public void validate(@PathVariable("sheet") String sheet, @RequestBody QuickAddRequest request, Settings settings,
            Periods periods, Out<QuickAddRequest> body, Out<ClaimInput> claim)
            throws InvalidPersonException, InvalidClaimException {
        String name = request == null || request.name() == null ? "" : request.name().trim();
        String amount = request == null || request.amount() == null ? "" : request.amount().trim();
        if (name.isBlank()) {
            throw new InvalidPersonException("A name is required");
        }
        if (!AMOUNT.matcher(amount).matches()) {
            throw new InvalidClaimException("The amount must be a number of 0.00 or more with up to two decimals");
        }
        ClaimInput input = new ClaimInput(new BigDecimal(amount), settings.entryDay(sheet), "");
        if (periods.closedOn(sheet, input.date())) {
            throw new InvalidClaimException("A claim may not be dated inside a closed period");
        }
        body.set(new QuickAddRequest(name, amount));
        claim.set(input);
    }
}
